UNITS.forEach(u=>{ if(MORE2[u.id]) MORE2[u.id].forEach(L=>u.lessons.push(L)); });

/* Words that are too close in meaning are never offered as wrong choices for each other. */
const NEAR = [['corroborate','validate','substantiate','concur'],['tentative','provisional','preliminary','inconclusive'],['resilient','robust','tenacious','steadfast'],
 ['meticulous','rigorous','diligent','comprehensive','exhaustive'],['negligible','marginal','meager','sparse','scarce'],['wary','apprehensive','skeptical'],['detached','aloof','dismissive'],
 ['foster','engender','bolster','advocate','induce'],['diminish','curtail','mitigate'],['contend','assert','qualify'],['convey','articulate','depict','evoke'],['compelling','cogent','lucid','plausible'],
 ['impede','deter','undermine'],['emulate','replicate'],['exacerbate','precipitate'],['unprecedented','unforeseen','novel'],['ambiguous','elusive','inconsistent'],['venerate','reverent'],
 ['prolific','abundant','myriad','ample','substantial'],['nostalgic','wistful'],['frugal','meager'],['zealous','earnest'],['dubious','skeptical','tenuous'],['infer','speculate','discern'],['impetuous','arbitrary','inadvertent'],
 ['robust','compelling','rigorous'],['convey','induce'],['methodology','premise'],['abundant','ubiquitous'],['qualify','curtail'],['tenuous','negligible'],
 ['ephemeral','transient','provisional','tentative'],['perennial','perpetual'],['nascent','novel','preliminary','rudimentary'],['archaic','obsolete'],['abrupt','unforeseen','impetuous'],['commend','extol','endorse','advocate'],['censure','rebuke','admonish','disparage','dismissive'],['reticent','aloof','detached'],['candor','candid'],['astute','perceptive','discern'],['esoteric','ambiguous'],['cognizant','wary'],['profound','substantial'],['autonomy','sovereign'],['consensus','concur'],['disparity','divergent','inconsistent'],['subsidize','bolster','foster'],['unilateral','arbitrary'],['mobilize','induce'],['acclaim','laudatory']];
const WORDS = VSETS.flatMap(s=>s.words.map(w=>w.slice(0,4)));

const VUNITS = VSETS.map((set,k)=>{
  const all = VSETS.flatMap((s,j)=>s.words.map(w=>({w,j})));
  const near = w => new Set(NEAR.filter(g=>g.includes(w)).flat());
  const cloze = (w,i) => {
    const bad = near(w[0]);
    const pool = all.filter(x=>x.j!==k && x.w[1]===w[1] && !bad.has(x.w[0])).map(x=>x.w);
    const pick = []; let h = (k*31 + i*17 + w[0].length) % pool.length;
    while(pick.length<3){ const c = pool[h % pool.length]; if(!pick.includes(c)) pick.push(c); h += 1; }
    return { p:w[4], q:Q_WORD, c:[w[0], ...pick.map(x=>x[0])], word:w[0], d:set.d||2,
      e:`"${w[0]}" means ${w[2]}, which fits the clue in the sentence. ` + pick.map(x=>`"${x[0]}" means ${x[2]}.`).join(' ') };
  };
  const ws = set.words;
  const A = [{t:'m', d:1, pairs:ws.slice(0,4).map(w=>[w[0],w[2]])}, ...ws.slice(0,5).map(cloze)];
  const B = [{t:'m', d:1, pairs:ws.slice(5,9).map(w=>[w[0],w[2]])}, ...ws.slice(5,10).map((w,i)=>cloze(w,i+5))];
  return { id:'v'+(k+1), sec:4, vocab:true, title:set.title, setNo:k+1,
    tip:'Read the whole sentence before the choices. Find the clue (a colon, "but," "because," an example), predict your own word, then pick the closest match.',
    lessons:[A,B] };
});
